def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    moderate_bids = []
    extreme_bids = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if bid <= 100:
                    moderate_bids.append(float(bid))
                else:
                    extreme_bids.append(float(bid))

    if not alive:
        return float(min(budget, 15.0))

    severe_risk = hp <= 3 or no_water >= 2
    high_risk = hp <= 5 or no_water >= 1
    abundant = supply >= 24
    medium = supply >= 20

    bob_like = max(moderate_bids) if moderate_bids else 70.0
    all_highest = max(prev_bids) if prev_bids else 70.0

    target = 0.0

    if severe_risk:
        if abundant:
            target = max(72.0, bob_like + 2.0)
        elif medium:
            target = max(78.0, bob_like + 4.0)
        else:
            target = max(88.0, min(110.0, bob_like + 8.0))
    elif high_risk:
        if abundant:
            target = 46.0
        elif medium:
            target = max(52.0, min(76.0, bob_like + 1.5))
        else:
            if all_highest > 120:
                target = 28.0
            else:
                target = max(58.0, min(82.0, bob_like + 2.0))
    else:
        if abundant:
            target = 18.0
        elif medium:
            target = 24.0 if all_highest > 120 else 34.0
        else:
            target = 12.0 if all_highest > 120 else 30.0

    reserve = 0.0
    if hp > 6 and no_water == 0:
        reserve = 35.0
    elif hp > 4:
        reserve = 20.0

    cap = max(0.0, budget - reserve)
    bid = min(target, cap)

    if severe_risk and bid < min(budget, 55.0):
        bid = min(budget, max(55.0, bid))

    if bid < 0:
        bid = 0.0
    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from traces to infer who is pressuring.
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # If someone already overpaid yesterday, avoid mirroring; bid enough to beat typical low bidders.
    # From yesterday: Bob ~70, Eric ~148, Alex died with very high bids.
    # Use a target that is between Bob and Eric, and higher when my HP is low.
    hp_pressure = 0.0
    if hp <= 2:
        hp_pressure = 1.0
    elif hp <= 4:
        hp_pressure = 0.7
    elif hp <= 6:
        hp_pressure = 0.4
    else:
        hp_pressure = 0.2

    # Supply affects how many water units exist; higher supply reduces urgency.
    # supply range is 15..25; map to a multiplier.
    if supply <= MIN_SUPPLY:
        supply_mult = 1.15
    elif supply >= MAX_SUPPLY:
        supply_mult = 0.95
    else:
        # linear interpolation
        supply_mult = 1.15 - (supply - MIN_SUPPLY) * (1.15 - 0.95) / (MAX_SUPPLY - MIN_SUPPLY)

    # Base target: aim around 0.55 salary, then adjust.
    base = DAILY_SALARY * 0.55

    # If highest previous bid is very high, cap our escalation to avoid volatility.
    if highest_prev_bid >= DAILY_SALARY * 0.95:
        # Someone tried to dominate; we respond moderately.
        base = DAILY_SALARY * (0.45 + 0.25 * hp_pressure)
    elif highest_prev_bid >= DAILY_SALARY * 0.7:
        # Eric-like pressure; bid high enough to compete.
        base = DAILY_SALARY * (0.6 + 0.25 * hp_pressure)
    else:
        # Mostly low bidders; bid mid.
        base = DAILY_SALARY * (0.5 + 0.3 * hp_pressure)

    # If we've already had no water for multiple days, increase.
    if no_water_days >= 2:
        base *= 1.15
    elif no_water_days >= 1:
        base *= 1.07

    target = base * supply_mult

    # Ensure we don't exceed budget.
    target = min(target, budget)

    # If budget is tiny, still bid something small but nonzero.
    if target <= 0.0:
        return 0.0

    # Add a small deterministic increment to break ties.
    # Keep within budget.
    tie_break = 1.0 + (day % 3) * 0.5
    target = min(budget, target + tie_break)

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    aggressive_bidders_active = False
    conservative_bidders_active = False

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None and prev['bid'] > 0:
            yesterday_bids.append(prev['bid'])
            opp_daily_salary = opp.get('daily_salary', DAILY_SALARY)
            if prev['bid'] >= opp_daily_salary * 0.9:
                aggressive_bidders_active = True
            elif prev['bid'] < opp_daily_salary * 0.7:
                conservative_bidders_active = True

    bid = DAILY_SALARY * 0.7

    if my_status['hp'] <= 2:
        bid = DAILY_SALARY * 1.2
    elif my_status['hp'] <= 4:
        bid = DAILY_SALARY * 1.0

    total_water_needed_by_all = WATER_REQ * (num_alive_opponents + 1)
    if day_context['supply'] < total_water_needed_by_all:
        bid *= 1.1
    elif day_context['supply'] > total_water_needed_by_all * 1.5:
        bid *= 0.9

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        lowest_prev_bid = min(yesterday_bids)

        if my_status['hp'] <= 4: 
            bid = max(bid, highest_prev_bid + 5)
        elif aggressive_bidders_active:
            if my_status['hp'] > 5 and my_status['budget'] > DAILY_SALARY * 3:
                bid = min(bid, highest_prev_bid * 0.9)
                bid = max(bid, DAILY_SALARY * 0.6)
            else:
                bid = max(bid, highest_prev_bid + 2)
        elif conservative_bidders_active and not aggressive_bidders_active:
            bid = min(bid, lowest_prev_bid + 5)
            bid = max(bid, DAILY_SALARY * 0.5)

    final_bid = min(my_status['budget'], bid)
    final_bid = max(final_bid, WATER_REQ * 1.0)

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['hp'] < 5:
        final_bid = my_status['budget']

    return final_bid
